#!/bin/sh
# Generated by `codeyam-editor editor devcontainer-setup`. Starts the CodeYam
# Editor and watches it: logs how each attempt ended, records it in
# .codeyam/run/codespaces-launch.json, and retries an editor that stopped before it
# ever answered. Run by postStartCommand, and by the ready script when it
# finds no editor running. To start the editor by hand:
#   sh .devcontainer/codeyam-start.sh attach

port=14199
reason="${1:-attach}"
deps="${2:-}"
log=.codeyam/logs/codespaces-editor.log
record=.codeyam/run/codespaces-launch.json

mkdir -p "$(dirname "$log")" "$(dirname "$record")"

# Typed into a terminal: detach, so closing the terminal does not stop it.
if [ -t 1 ]; then
  setsid -f nohup sh .devcontainer/codeyam-start.sh "$reason" >> .codeyam/logs/codespaces-editor.log 2>&1 < /dev/null
  echo "Starting the CodeYam Editor in the background. Its output: $log"
  echo 'To wait for its link, run: sh .devcontainer/codeyam-ready.sh'
  exit 0
fi

field() {
  sed -n "s/.*\"$1\":\"\{0,1\}\([^,\"}]*\).*/\1/p" "$record" 2>/dev/null
}

# One launcher at a time: postStart and an attach can race.
other=$(field supervisor)
if [ -n "$other" ] && [ "$other" != "$$" ] && kill -0 "$other" 2>/dev/null; then
  echo "--- launcher already running (pid $other); not starting another ---"
  exit 0
fi

# Append, never truncate: keep the previous attempt's evidence.
if [ -f "$log" ] && [ "$(wc -c < "$log")" -gt 1048576 ]; then
  mv -f "$log" "$log.1"
fi
exec >> "$log" 2>&1 < /dev/null

stamp() { date -u +%Y-%m-%dT%H:%M:%SZ; }

case "$deps" in
  '') deps_json=null ;;
  0) deps_json='"ok"' ;;
  *) deps_json='"failed"'
     echo "--- $(stamp) system-deps repair exited $deps; starting the editor anyway ---" ;;
esac

# state attempt [pid] [exitCode] [signal]
write_record() {
  printf '{"state":"%s","reason":"%s","attempt":%s,"supervisor":%s,"pid":%s,"exitCode":%s,"signal":%s,"depsRepair":%s,"at":"%s"}\n' \
    "$1" "$reason" "$2" "$$" "${3:-null}" "${4:-null}" "${5:-null}" "$deps_json" "$(stamp)" \
    > "$record.tmp" && mv -f "$record.tmp" "$record"
}

attempt=1
for backoff in 2 5 10 last; do
  echo "--- launch attempt $attempt ($reason) at $(stamp) ---"
  write_record starting "$attempt"
  codeyam-editor start --hosted --no-open --port 14199 &
  child=$!
  write_record running "$attempt" "$child"
  answered=0
  while kill -0 "$child" 2>/dev/null; do
    if [ "$answered" = 0 ] && curl -s -o /dev/null --max-time 2 "http://127.0.0.1:$port/"; then
      answered=1
    fi
    sleep 2
  done
  wait "$child"
  code=$?
  if [ "$code" -gt 128 ]; then
    sig=$(kill -l "$((code - 128))" 2>/dev/null || echo "$((code - 128))")
    echo "--- $(stamp) CodeYam Editor (pid $child) killed by signal $sig ---"
    write_record exited "$attempt" "$child" null "\"$sig\""
  else
    echo "--- $(stamp) CodeYam Editor (pid $child) exited code=$code ---"
    write_record exited "$attempt" "$child" "$code"
  fi
  # It served and then stopped (someone stopped it): not a failed launch.
  [ "$answered" = 1 ] && exit 0
  if [ "$backoff" = last ]; then
    echo "--- $(stamp) gave up after 4 attempts ---"
    if [ "$code" -gt 128 ]; then
      write_record gave-up "$attempt" "$child" null "\"$sig\""
    else
      write_record gave-up "$attempt" "$child" "$code"
    fi
    exit 1
  fi
  sleep "$backoff"
  attempt=$((attempt + 1))
done
